        .field(PgTypes.textArray.opt(), Product::tags)
        .field(dimensionsType.opt(), Product::dimensions)
        .field(PgTypes.jsonb.opt(), Product::metadata)
        .field(PgTypes.timestamptz.opt(), Product::createdAt)
        .build(Product::new);

